window.products.push({"id":1023002,"name":"Twine, Brie Baker with Lid, Acacia Wood Spreader, White Ceramic, Set of 1","category":"homeandappliances","retail price":31.61,"sale price":null,"image":"https://m.media-amazon.com/images/I/61+zXNeVOeL._AC_SL1500_.jpg","description":"When it comes to guest-pleasing hors d'oeuvres, nothing beats baked brie. Our stoneware baker makes preparing this delectable dish easier than ever: simply top with a drizzle of honey or spread of your favorite jam, bake for 15 minutes in a 350 degree oven, & enjoy! White ceramic brie baker with lid and handles. 7 inch diameter. Oven-safe up to 350 degrees Fahrenheit. Includes acacia wood spreader.","images":["https://m.media-amazon.com/images/I/61+zXNeVOeL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Twine","source_asin":"B079ZT8ZGS","category_path":"Home & Kitchen"},"sku":"BM-1023002","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B079ZT8ZGS","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B079ZT8ZGS","price_pending":true,"merchant_ready":false});
