window.products.push({"id":1023866,"name":"Park Hill Collection EAB80848 Nesting Birds Decorative Box, 7-inch Length","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/711aOs0mkLL._AC_SL1200_.jpg","description":"The Park Hill Collection is a gathering of objects selected that bring happy memories of childhood and things we just fell in love with. Many are exclusive antique reproductions to help satisfy our nostalgic desire for the way things used to be and yet timeless for contemporary living. Combining these objects in various ways will create a personal statement all your own. Whether looking for period charm, a style of elegant restraint or just wanting to infuse a spirit of playfulness, you'll find it here.","images":["https://m.media-amazon.com/images/I/711aOs0mkLL._AC_SL1200_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Park Hill Collection","source_asin":"B08SMKHYSX","category_path":"Home & Kitchen"},"sku":"BM-1023866","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B08SMKHYSX","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B08SMKHYSX","price_pending":true,"merchant_ready":false});
window.products.push({"id":1023867,"name":"Amsterdam Ceramic Teapot Warmer - Black","category":"homeandappliances","retail price":8.32,"sale price":null,"image":"https://m.media-amazon.com/images/I/31dLrZdrNSL._AC_.jpg","description":"This Amsterdam ceramic teapot warmer will accommodate any of your ceramic teapots regardless of size. These beautifully glazed ceramic warmers are available in an array of vivid colors. This warmer allows for a candle tea light (not included) to sit in the interior compartment with an open window to allow your teapot to stay warm. The Amsterdam Ceramic Teapot Warmer is dishwasher and microwave safe. Dimensions: 5 inches in length, 2.5 inches in height","images":["https://m.media-amazon.com/images/I/31dLrZdrNSL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Metropolitan Tea","source_asin":"B00864KXWW","category_path":"Home & Kitchen"},"sku":"BM-1023867","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00864KXWW","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00864KXWW","price_pending":true,"merchant_ready":false});
